dashboard.definition:
{
  "title": "VPN Sessions",
  "description": "Aviatrix User VPN: who is connected, from where, for how long, how much data they moved, and which sessions deserve a second look.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "time",
        "defaultValue": "-7d@d,now"
      }
    },
    "input_user": {
      "type": "input.text",
      "title": "User",
      "options": {
        "token": "user",
        "defaultValue": "*"
      }
    },
    "input_gateway": {
      "type": "input.text",
      "title": "VPN gateway",
      "options": {
        "token": "gateway",
        "defaultValue": "*"
      }
    },
    "input_src": {
      "type": "input.text",
      "title": "Client public IP",
      "options": {
        "token": "src",
        "defaultValue": "*"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$time.earliest$",
            "latest": "$time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_8": {
      "type": "splunk.singlevalue",
      "title": "Sessions started",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_9": {
      "type": "splunk.singlevalue",
      "title": "Still connected",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#0ca30c",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_10": {
      "type": "splunk.singlevalue",
      "title": "Users",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_11": {
      "type": "splunk.singlevalue",
      "title": "Client public IPs",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_12": {
      "type": "splunk.singlevalue",
      "title": "Data transferred",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_13": {
      "type": "splunk.singlevalue",
      "title": "Avg session",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_15": {
      "type": "splunk.table",
      "title": "Open sessions",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 6,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small"
      },
      "description": "Connected in range with no disconnect logged, and the virtual IP not since reassigned"
    },
    "viz_section_16": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "#### SESSIONS WORTH A LOOK\nLogins from more than one country, very large transfers, very long sessions, or many client IPs.",
        "fontColor": "#c3c2b7",
        "fontSize": "custom",
        "customFontSize": 13,
        "backgroundColor": "transparent"
      }
    },
    "viz_18": {
      "type": "splunk.table",
      "title": "Unusual sessions",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 6,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small"
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "user",
                "key": "row.User.value"
              }
            ]
          }
        }
      ]
    },
    "viz_section_19": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "#### TRENDS AND CLIENTS",
        "fontColor": "#c3c2b7",
        "fontSize": "custom",
        "customFontSize": 13,
        "backgroundColor": "transparent"
      }
    },
    "viz_22": {
      "type": "splunk.column",
      "title": "Sessions started by gateway",
      "dataSources": {
        "primary": "ds_20"
      },
      "options": {
        "backgroundColor": "#17181b",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#3987e5",
          "#d95926",
          "#199e70",
          "#c98500",
          "#d55181",
          "#0ca30c",
          "#9085e9",
          "#e66767"
        ],
        "yAxisTitleVisibility": "hide",
        "stackMode": "stacked"
      }
    },
    "viz_23": {
      "type": "splunk.table",
      "title": "Client platform and version",
      "dataSources": {
        "primary": "ds_21"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 6,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small"
      }
    },
    "viz_section_24": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "#### WHERE USERS CONNECT FROM",
        "fontColor": "#c3c2b7",
        "fontSize": "custom",
        "customFontSize": 13,
        "backgroundColor": "transparent"
      }
    },
    "viz_27": {
      "type": "splunk.map",
      "title": "Client locations",
      "dataSources": {
        "primary": "ds_25"
      },
      "options": {
        "center": [
          30,
          -20
        ],
        "zoom": 1.3,
        "layers": [
          {
            "type": "bubble",
            "latitude": "> primary | seriesByName(\"latitude\")",
            "longitude": "> primary | seriesByName(\"longitude\")",
            "bubbleSize": "> primary | seriesByName(\"count\")",
            "dataColors": "#3987e5"
          }
        ]
      }
    },
    "viz_28": {
      "type": "splunk.table",
      "title": "Client public IPs",
      "dataSources": {
        "primary": "ds_26"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 8,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small"
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "src",
                "key": "row.Client public IP.value"
              }
            ]
          }
        }
      ]
    },
    "viz_section_29": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "#### USERS AND SESSION EVENTS",
        "fontColor": "#c3c2b7",
        "fontSize": "custom",
        "customFontSize": 13,
        "backgroundColor": "transparent"
      }
    },
    "viz_31": {
      "type": "splunk.table",
      "title": "Users",
      "dataSources": {
        "primary": "ds_30"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 7,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small"
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "user",
                "key": "row.User.value"
              }
            ]
          }
        }
      ]
    },
    "viz_33": {
      "type": "splunk.table",
      "title": "Session events",
      "dataSources": {
        "primary": "ds_32"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 12,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "Status": {
            "rowColors": "> table | seriesByName(\"Status\") | matchValue(colors0)"
          }
        }
      },
      "context": {
        "colors0": [
          {
            "match": "Allowed",
            "value": "#86b6ef"
          },
          {
            "match": "Would block",
            "value": "#fab219"
          },
          {
            "match": "Blocked",
            "value": "#ff8a85"
          },
          {
            "match": "Critical",
            "value": "#ff8a85"
          },
          {
            "match": "High",
            "value": "#f4a27f"
          },
          {
            "match": "Medium",
            "value": "#fab219"
          },
          {
            "match": "Low",
            "value": "#86b6ef"
          },
          {
            "match": "Info",
            "value": "#c3c2b7"
          },
          {
            "match": "Healthy",
            "value": "#4cc94c"
          },
          {
            "match": "Warning",
            "value": "#fab219"
          },
          {
            "match": "Silent",
            "value": "#c3c2b7"
          },
          {
            "match": "Up",
            "value": "#4cc94c"
          },
          {
            "match": "Down",
            "value": "#ff8a85"
          },
          {
            "match": "Detected",
            "value": "#fab219"
          },
          {
            "match": "success",
            "value": "#4cc94c"
          },
          {
            "match": "failure",
            "value": "#ff8a85"
          },
          {
            "match": "created",
            "value": "#4cc94c"
          },
          {
            "match": "modified",
            "value": "#86b6ef"
          },
          {
            "match": "deleted",
            "value": "#ff8a85"
          },
          {
            "match": "read",
            "value": "#898781"
          },
          {
            "match": "active",
            "value": "#4cc94c"
          },
          {
            "match": "disconnected",
            "value": "#898781"
          }
        ]
      }
    }
  },
  "dataSources": {
    "ds_vpn_base": {
      "type": "ds.search",
      "name": "ds_vpn_base",
      "options": {
        "query": "`aviatrix_vpn`\n| `aviatrix_vpn_fields`\n| search user=$user|s$ dvc=$gateway|s$\n| where \"$src$\"=\"*\" OR src=\"$src$\"\n| fields _time, session_id, vpn_status, user, src, dest_ip, dvc, vpn_login, vpn_logout, duration, bytes_in, bytes_out, bytes, client_platform, client_version"
      }
    },
    "ds_2": {
      "type": "ds.chain",
      "name": "ds_2",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"active\"\n| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_3": {
      "type": "ds.chain",
      "name": "ds_3",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| stats min(_time) as connected values(vpn_status) as states latest(src) as src latest(client_platform) as platform latest(client_version) as client by session_id, user, dvc, dest_ip\n| eventstats max(connected) as newest by dvc, dest_ip\n| where isnull(mvfind(states, \"^disconnected$\")) AND connected=newest | stats count as value"
      }
    },
    "ds_4": {
      "type": "ds.chain",
      "name": "ds_4",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| stats dc(user) as value"
      }
    },
    "ds_5": {
      "type": "ds.chain",
      "name": "ds_5",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| stats dc(src) as value"
      }
    },
    "ds_6": {
      "type": "ds.chain",
      "name": "ds_6",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"disconnected\" | stats sum(bytes) as b\n| eval value=`aviatrix_bytes_format(coalesce(b, 0))`"
      }
    },
    "ds_7": {
      "type": "ds.chain",
      "name": "ds_7",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"disconnected\" | stats avg(duration) as d\n| eval value=`aviatrix_duration_format(round(coalesce(d, 0)))`"
      }
    },
    "ds_14": {
      "type": "ds.chain",
      "name": "ds_14",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| stats min(_time) as connected values(vpn_status) as states latest(src) as src latest(client_platform) as platform latest(client_version) as client by session_id, user, dvc, dest_ip\n| eventstats max(connected) as newest by dvc, dest_ip\n| where isnull(mvfind(states, \"^disconnected$\")) AND connected=newest\n| eval \"Connected for\"=tostring(now()-connected, \"duration\"), Connected=strftime(connected, \"%Y-%m-%d %H:%M:%S\")\n| sort - connected\n| rename user as User, dvc as Gateway, dest_ip as \"Virtual IP\", src as \"Client public IP\", platform as Platform, client as Client\n| table Connected \"Connected for\" User Gateway \"Virtual IP\" \"Client public IP\" Platform Client"
      }
    },
    "ds_17": {
      "type": "ds.chain",
      "name": "ds_17",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| eventstats dc(src) as user_ips by user\n| iplocation src\n| eventstats dc(Country) as user_countries values(Country) as countries by user\n| eval reason=mvappend(if(user_countries>1, \"Logins from \".user_countries.\" countries: \".mvjoin(countries, \", \"), null()), if(bytes>1073741824, \"Transferred \".`aviatrix_bytes_format(bytes)`, null()), if(duration>43200, \"Session lasted \".tostring(duration, \"duration\"), null()), if(user_ips>3, user_ips.\" client IPs\", null()))\n| where isnotnull(reason)\n| stats values(reason) as Why count as Events values(src) as ips values(dvc) as gw max(_time) as last by user\n| eval \"Client IPs\"=mvjoin(mvindex(ips, 0, 3), \", \"), Gateways=mvjoin(gw, \", \"), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\")\n| rename user as User\n| table User Why \"Client IPs\" Gateways Events \"Last seen\""
      }
    },
    "ds_20": {
      "type": "ds.chain",
      "name": "ds_20",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"active\" | timechart count by dvc"
      }
    },
    "ds_21": {
      "type": "ds.chain",
      "name": "ds_21",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"active\"\n| stats count as Sessions dc(user) as Users by client_platform client_version\n| sort - Sessions\n| rename client_platform as Platform, client_version as Version"
      }
    },
    "ds_25": {
      "type": "ds.chain",
      "name": "ds_25",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"active\" AND isnotnull(src)\n| iplocation src\n| where isnotnull(lat)\n| stats count by lat lon\n| rename lat as latitude, lon as longitude"
      }
    },
    "ds_26": {
      "type": "ds.chain",
      "name": "ds_26",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| where vpn_status=\"active\" AND isnotnull(src)\n| stats count as Sessions values(user) as Users max(_time) as last by src\n| iplocation src\n| eval Location=coalesce(nullif(mvjoin(mvappend(nullif(City, \"\"), nullif(Region, \"\"), nullif(Country, \"\")), \", \"), \"\"), \"private / unknown\"), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\")\n| sort - Sessions\n| rename src as \"Client public IP\"\n| table \"Client public IP\" Location Users Sessions \"Last seen\""
      }
    },
    "ds_30": {
      "type": "ds.chain",
      "name": "ds_30",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| stats dc(eval(if(vpn_status=\"active\", session_id, null()))) as Sessions sum(duration) as seconds sum(bytes_in) as bin sum(bytes_out) as bout dc(src) as \"Client IPs\" latest(_time) as last by user\n| sort - seconds\n| eval \"Connected time\"=if(isnull(seconds), \"-\", tostring(seconds, \"duration\")), \"From clients\"=if(isnull(bin), \"-\", `aviatrix_bytes_format(bin)`), \"To clients\"=if(isnull(bout), \"-\", `aviatrix_bytes_format(bout)`), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\")\n| rename user as User\n| table User Sessions \"Connected time\" \"From clients\" \"To clients\" \"Client IPs\" \"Last seen\""
      }
    },
    "ds_32": {
      "type": "ds.chain",
      "name": "ds_32",
      "options": {
        "extend": "ds_vpn_base",
        "query": "| sort - _time | head 500\n| eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), Length=if(isnotnull(duration), tostring(duration, \"duration\"), \"\"), Data=if(isnotnull(bytes), `aviatrix_bytes_format(bytes)`, \"\")\n| rename vpn_status as Status, user as User, dvc as Gateway, dest_ip as \"Virtual IP\", src as \"Public IP\", client_platform as Platform, client_version as Client\n| table Time Status User Gateway \"Virtual IP\" \"Public IP\" Length Data Platform Client"
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 2408
    },
    "structure": [
      {
        "item": "viz_8",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_9",
        "type": "block",
        "position": {
          "x": 240,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_10",
        "type": "block",
        "position": {
          "x": 480,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_11",
        "type": "block",
        "position": {
          "x": 720,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_12",
        "type": "block",
        "position": {
          "x": 960,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_13",
        "type": "block",
