          "x": 1200,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_15",
        "type": "block",
        "position": {
          "x": 0,
          "y": 150,
          "w": 1440,
          "h": 300
        }
      },
      {
        "item": "viz_section_16",
        "type": "block",
        "position": {
          "x": 0,
          "y": 450,
          "w": 1440,
          "h": 76
        }
      },
      {
        "item": "viz_18",
        "type": "block",
        "position": {
          "x": 0,
